SELECT *
FROM ed2k_download_task
WHERE task_uuid = #{taskUuid}
  AND user_id = #{userId}
  AND deleted = 0

SELECT *
FROM ed2k_download_task
WHERE user_id = #{userId}
  AND resource_id = #{resourceId}
  AND deleted = 0

SELECT *
FROM ed2k_download_task
WHERE user_id = #{userId}
  AND deleted = 0
ORDER BY created_at DESC, id DESC
LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE ed2k_download_task
SET deleted       = id,
    desired_state = 'DELETED',
    revision      = revision + 1,
    updated_at    = CURRENT_TIMESTAMP
WHERE id = #{id}
  AND task_uuid = #{taskUuid}
  AND user_id = #{userId}
  AND deleted = 0
